//! WPT `fetch/orb/tentative/img-mime-types-coverage.tentative.sub.html` (the
//! two lists of `Content-Type`s a cross-origin, `nosniff` PNG is served with:
//! `passes` are let through, `fails` blocked) and
//! `resources/png-mislabeled-as-html.png.headers` (the `Content-Type` of a
//! PNG mislabeled as HTML), as constants for `clazel-fetch`'s
//! `tests/conformance_orb.rs`. The other vendored pages are read by a person
//! (their meaning is written as rows there); they are inputs only so that a
//! change upstream is seen.
//!
//! The converter fails on anything it does not recognise: a list that is not
//! `var passes = [` or `var fails = [` followed by string literals and `//`
//! comments, or a `.headers` file that is not one `Content-Type:` line.

use std::fmt::Write as _;
use std::path::Path;

/// The files vendored for this suite (besides LICENSE.md and SOURCE.md).
pub const FILES: &[&str] = &[
    "img-mime-types-coverage.tentative.sub.html",
    "img-png-mislabeled-as-html.sub.html",
    "img-png-mislabeled-as-html.sub-ref.html",
    "img-png-unlabeled.sub.html",
    "img-png-unlabeled.sub-ref.html",
    "png-mislabeled-as-html.png.headers",
];

/// The string literals of the array `var <name> = [ ... ]` in `html`.
fn list(html: &str, name: &str) -> Result<Vec<String>, String> {
    let head = format!("var {name} = [");
    let start = html.find(&head).ok_or(format!("no `{head}`"))?;
    let rest = html.get(start + head.len()..).unwrap_or_default();
    let end = rest.find(']').ok_or(format!("`{head}` is not closed"))?;
    let body = rest.get(..end).unwrap_or_default();
    let mut out = Vec::new();
    for line in body.lines() {
        let t = line.trim();
        if t.is_empty() || t.starts_with("//") {
            continue;
        }
        let t = t.strip_suffix(',').unwrap_or(t);
        let s = t
            .strip_prefix('"')
            .and_then(|t| t.strip_suffix('"'))
            .ok_or(format!("{name}: not a string literal: {t:?}"))?;
        if s.contains(['"', '\\']) {
            return Err(format!("{name}: escape in {s:?}"));
        }
        out.push(s.to_owned());
    }
    Ok(out)
}

fn literals(name: &str, items: &[String], out: &mut String) -> Result<(), String> {
    writeln!(
        out,
        "/// Content-Types of the page's `{}` list.
pub const {name}: &[&str] = &[",
        name.to_lowercase()
    )
    .map_err(|e| e.to_string())?;
    for s in items {
        writeln!(out, "    {s:?},").map_err(|e| e.to_string())?;
    }
    out.push_str("];\n");
    Ok(())
}

pub fn convert(dir: &Path) -> Result<String, String> {
    let page = "img-mime-types-coverage.tentative.sub.html";
    let html = std::fs::read_to_string(dir.join(page)).map_err(|e| format!("{page}: {e}"))?;
    let passes = list(&html, "passes").map_err(|e| format!("{page}: {e}"))?;
    let fails = list(&html, "fails").map_err(|e| format!("{page}: {e}"))?;
    if passes.is_empty() || fails.is_empty() {
        return Err(format!("{page}: an empty list"));
    }
    let headers_file = "png-mislabeled-as-html.png.headers";
    let headers = std::fs::read_to_string(dir.join(headers_file))
        .map_err(|e| format!("{headers_file}: {e}"))?;
    let mislabeled = headers
        .trim()
        .strip_prefix("Content-Type:")
        .map(str::trim)
        .filter(|v| !v.is_empty() && !v.contains('\n'))
        .ok_or(format!(
            "{headers_file}: not one `Content-Type:` line: {headers:?}"
        ))?;
    let mut out = String::new();
    out.push_str("// @generated by `cargo xtask testdata` from tests/data/wpt-orb/.\n");
    out.push_str("// Do not edit: `cargo xtask verify` fails if this differs from what the\n");
    out.push_str("// converter (xtask/src/testdata/wpt_orb.rs) produces.\n");
    out.push_str("// Source, commit and license: tests/data/wpt-orb/SOURCE.md.\n");
    literals("PASSES", &passes, &mut out)?;
    literals("FAILS", &fails, &mut out)?;
    writeln!(
        out,
        "/// The Content-Type of the PNG mislabeled as HTML.
pub const MISLABELED_CONTENT_TYPE: &str = {mislabeled:?};"
    )
    .map_err(|e| e.to_string())?;
    Ok(out)
}
